    q("fx_080","Margen bruto por familia en el trimestre actual","Cual es el margen bruto de cada familia en los ultimos 3 meses?","SUM((PRECIO-PRECIOCOSTE)*CANTIDAD) por familia en DOCLIN JOIN DOCCAB TIPO=13 con FECHA>=date('now','-90 days').","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS VENTAS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*A.PRECIOCOSTE),2) AS COSTE, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*(CAST(L.PRECIO AS REAL)-A.PRECIOCOSTE)),2) AS MARGEN FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=13 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE A.PRECIOCOSTE>0 AND D.FECHA>=date('now','-90 days') GROUP BY A.CODFAMILIA ORDER BY MARGEN DESC LIMIT 20","Finanzas","Director","Financiero","Alto","",""),
